const t=[{id:"notes/Omics/genomics/bwa/bwa",title:"BWA MEM 比对人类基因组实战",tags:["BWA","基因组比对","NGS","命令行","人类基因组","SAM/BAM"],path:"notes/Omics/genomics/bwa/bwa",content:"BWA MEM 比对人类基因组实战 基本命令 # 索引参考基因组 bwa index ref.fa # 比对双端测序数据 bwa mem -t 8 ref.fa read1.fq read2.fq > output.sam # 转换为BAM格式并排序 samtools view -bS output.sam | samtools sort -o output.bam 参数优化 -t : 线程数，根据服务器配置调整 -M : 标记较短的split hits为secondary -R : 添加read group信息"},{id:"notes/Omics/proteomics/maxquant/maxquant",title:"MaxQuant 蛋白质组学分析工作流",tags:["MaxQuant","蛋白质组学","质谱分析","生物信息学","定量分析"],path:"notes/Omics/proteomics/maxquant/maxquant",content:"MaxQuant 蛋白质组学分析工作流 基本配置 输入文件设置 RAW 文件：质谱原始数据 FASTA 文件：蛋白质数据库 主要参数 酶切方式：Trypsin/P 最大漏切位点：2 前体质量容差：20 ppm（一级） 碎片离子容差：0.5 Da（二级） 分析流程 # 运行 MaxQuant mono MaxQuantCmd.exe mqpar.xml 典型输出文件： evidence.txt：肽段鉴定结果 proteinGroups.txt：蛋白质定量结果 summary.txt：分析统计摘要"},{id:"notes/Omics/transcriptomics/rnaseq-hisat2/rnaseq-hisat2",title:"RNA-Seq 分析：HISAT2 比对流程",tags:["RNA-Seq","HISAT2","转录组","比对","生物信息学"],path:"notes/Omics/transcriptomics/rnaseq-hisat2/rnaseq-hisat2",content:"RNA-Seq 分析：HISAT2 比对流程 HISAT2 特点 支持拼接感知的比对 高效的索引结构 适用于各种长度的RNA-Seq reads 基本命令 # 构建索引 hisat2-build ref.fa ref_index # 比对RNA-Seq数据 hisat2 -x ref_index -1 read1.fq -2 read2.fq -S output.sam"},{id:"notes/Programming/python/biopython/biopython",title:"Biopython 生物信息学应用",tags:["Python","Biopython","生物信息学","序列分析","基因组学"],path:"notes/Programming/python/biopython/biopython",content:'Biopython 生物信息学应用 序列操作 from Bio import SeqIO from Bio.Seq import Seq # 读取FASTA文件 for record in SeqIO.parse( "sequences.fasta" , "fasta" ): print (record. id , len (record.seq)) # 序列翻译 dna_seq = Seq( "ATGGCCATTGTAATGGGCCGCTGAAAGGGTGCCCGATAG" ) protein_seq = dna_seq.translate()'},{id:"notes/Programming/python/fastq/fastq",title:"用 Pandas 处理 FASTQ 质量统计",tags:["Python","Pandas","FASTQ","数据清洗","生物信息","入门"],path:"notes/Programming/python/fastq/fastq",content:'用 Pandas 处理 FASTQ 质量统计 简要示例：读取 fastqc_data.txt 并提取基本统计： import pandas as pd df = pd.read_csv( "fastqc_data.txt" , sep= "\\t" , comment= "#" ) print (df.head())'},{id:"notes/Programming/python/pandas/pandas",title:"Python Pandas 数据处理实战",tags:["Python","Pandas","数据处理","数据分析","数据清洗"],path:"notes/Programming/python/pandas/pandas",content:"Python Pandas 数据处理实战 数据读取 import pandas as pd # 读取CSV文件 df = pd.read_csv( 'data.csv' ) # 读取Excel文件 df = pd.read_excel( 'data.xlsx' ) 数据清洗 # 处理缺失值 df.fillna( 0 , inplace= True ) # 删除重复行 df.drop_duplicates(inplace= True )"},{id:"notes/Programming/r/demo/demo",title:"R语言数据处理示例",tags:["R语言","数据处理","统计分析","数据可视化","生物信息学"],path:"notes/Programming/r/demo/demo",content:'R语言数据处理示例 数据读取与基本操作 # 读取 CSV 文件 data &#x3C;- read.csv ( "expression_data.csv" ) # 查看数据结构 str ( data ) head ( data ) # 基本统计 summary ( data ) 数据可视化 # 安装并加载 ggplot2 install.packages ( "ggplot2" ) library ( ggplot2 ) # 创建散点图 ggplot ( data , aes ( x = Condition , y = Expression ) ) + geom_boxplot ( ) + theme_minimal ( ) + labs ( title = "基因表达水平比较" ) 统计分析 # t检验 t_test_result &#x3C;- t.test ( Expression ~ Condition , data = data ) print ( t_test_result )'},{id:"notes/Programming/r/ggplot2/ggplot2",title:"R语言 ggplot2 数据可视化",tags:["R语言","ggplot2","数据可视化","统计图表","生物信息学"],path:"notes/Programming/r/ggplot2/ggplot2",content:'R语言 ggplot2 数据可视化 基本语法 library ( ggplot2 ) # 创建散点图 ggplot ( data , aes ( x = expression , y = condition ) ) + geom_point ( ) + theme_minimal ( ) + labs ( title = "基因表达散点图" ) 常用图表类型 箱线图： geom_boxplot() 柱状图： geom_bar() 线图： geom_line()'},{id:"notes/Programming/shell/bash/bash",title:"Bash Shell 脚本编程",tags:["Shell","Bash","命令行","脚本编程","自动化"],path:"notes/Programming/shell/bash/bash",content:'Bash Shell 脚本编程 基本语法 #!/bin/bash # 变量定义 input_file= "data.fastq" output_dir= "results" # 条件判断 if [ -f " $input_file " ]; then echo "文件存在" else echo "文件不存在" fi 循环处理 # 遍历文件 for file in *.fastq; do echo "处理文件: $file " done'},{id:"projects/Biocrawler/api/api-demo/api-demo",title:"BioCrawler API 接口文档",tags:[],path:"projects/Biocrawler/api/api-demo/api-demo",content:'BioCrawler API 接口文档 以下内容皆为虚构！ 接口概述 提供 RESTful API 接口，支持生物数据的查询和下载。 核心接口 1. 序列查询接口 GET /api/v1/sequence/{accession_id} 参数说明： accession_id : 数据库登录号（如：NM_001301717） 返回示例： { "accession" : "NM_001301717" , "sequence" : "ATGGCCATTGTAATGGGCCGCTGAAAGGGTGCCCGATAG" , "length" : 38 , "organism" : "Homo sapiens" } 2. 批量下载接口 POST /api/v1/batch 请求体： { "accessions" : [ "NM_001301717" , "NM_001301718" ] , "format" : "fasta" } 认证方式 # 使用 API Key curl -H "X-API-Key: your_key_here" \\ https://api.biocrawler.example.com/api/v1/sequence/NM_001301717 错误处理 状态码 说明 200 成功 404 数据不存在 429 请求频率限制 500 服务器错误 使用限制 免费版：每小时 100 次请求 专业版：每小时 1000 次请求'},{id:"projects/Biocrawler/installation/installation-demo/installation-demo",title:"BioCrawler 安装指南",tags:[],path:"projects/Biocrawler/installation/installation-demo/installation-demo",content:'BioCrawler 安装指南 以下内容皆为虚构！ 环境要求 Python 3.8+ pip 20.0+ 操作系统：Windows 10+, macOS 10.15+, Linux 快速安装 1. 使用 pip 安装 pip install biocrawler 2. 从源码安装 git clone https://github.com/example/biocrawler.git cd biocrawler pip install -e . 配置设置 创建配置文件 # 初始化配置 biocrawler init # 编辑配置文件 nano ~/.biocrawler/config.yaml 配置示例 api: key: "your_api_key_here" timeout: 30 database: cache_dir: "~/.biocrawler/cache" max_cache_size: 10GB download: threads: 4 retries: 3 验证安装 # 测试连接 biocrawler test # 查看版本 biocrawler --version # 显示帮助 biocrawler -- help 常见问题 Q: 安装失败怎么办？ A: 确保 Python 版本 >= 3.8，并尝试更新 pip Q: 如何更新？ A: pip install --upgrade biocrawler Docker 安装 docker pull biocrawler/biocrawler:latest docker run -it biocrawler/biocrawler:latest'},{id:"topics/StructureOfProteinDemo/methods/methods-demo/methods-demo",title:"实验方法",tags:[],path:"topics/StructureOfProteinDemo/methods/methods-demo/methods-demo",content:"实验方法 以下内容皆为虚构！ 1. 样品制备 蛋白质表达与纯化 # 表达系统 宿主：E. coli BL21(DE3) 诱导条件：0.5 mM IPTG, 18°C, 16小时 # 纯化步骤 1. Ni-NTA 亲和层析 2. 凝胶过滤层析 (Superdex 200) 3. 浓缩至 3 mg/mL 负染电镜筛选 染色剂：2% 醋酸铀酰 数据采集：200 kV, 50,000x 放大倍数 筛选标准：单分散、完整颗粒 2. 冷冻电镜数据采集 样品制备 3 μL 样品滴加在 Quantifoil R1.2/1.3 网格 滤纸吸干，液氮快速冷冻 工作温度：-180°C 采集参数 参数 值 加速电压 300 kV 像素尺寸 1.5 Å 电子剂量 50 e⁻/Å² 帧数 50 frames 3. 数据处理 运动矫正 软件：MotionCor2 修正帧间运动和漂移 颗粒挑选 方法：模板匹配 软件：RELION 3.1 颗粒数量：~50,000 二维分类 类别数：20 选择标准：清晰特征 4. 三维重建 初始模型 方法：随机圆锥重构 分辨率：~8 Å 精细重建 迭代：20 轮 分辨率：3.0 Å 分辨率标准：FSC 0.143 5. 模型构建与优化 初始模型搭建 软件：Coot 方法：自动建模 + 手动修正 结构优化 软件：Phenix.refine 优化内容： 原子坐标 温度因子 占有率 质量验证 Ramachandran plot：96.5% 优势区域 几何偏差：键长 0.01 Å，键角 1.2° MolProbity score：1.8"},{id:"topics/StructureOfProteinDemo/results/results-demo/results-demo",title:"实验结果",tags:[],path:"topics/StructureOfProteinDemo/results/results-demo/results-demo",content:"实验结果 以下内容皆为虚构！ 1. 数据采集统计 数据质量评估 指标 结果 总图像数 2,500 微graphs 总剂量 50 e⁻/Å² 信噪比 15:1 颗粒总数 52,347 运动矫正效果 矫正前漂移：~50 Å 矫正后漂移：&#x3C; 2 Å 帧间相关性：> 0.95 2. 二维分类结果 代表性2D类平均图 显示明显的二级结构特征 颗粒分布均匀，无明显聚集 背景干净，污染少 分类统计 有效类别：8/20 保留颗粒数：38,245 丢弃原因：模糊、聚集、污染 3. 三维重建结果 分辨率评估 FSC 0.143：3.0 Å FSC 0.5：2.8 Å 分辨率分布：各向同性 电子密度图质量 主链密度：连续清晰 侧链密度：大部分可见 环区密度：部分模糊 4. 模型质量 结构特征 残基数：428 配体：ATP (1个) 水分子：126 金属离子：Mg²⁺ (2个) 几何质量 键长 RMSD：0.012 Å 键角 RMSD：1.3° 扭转角异常：3.2% 拉马钱德兰图 优势区域：96.5% 允许区域：3.2% 异常区域：0.3% 5. 结构功能分析 活性位点 ATP 结合口袋：残基 45-60 金属离子结合位点：残基 120-130, 200-210 底物通道：残基 250-280 结构比较 与同源蛋白相似度：78% 关键功能区域：高度保守 构象差异：活性位点开放状态 6. 结论 本研究成功解析了目标蛋白的三维结构，分辨率达到 3.0 Å，模型质量良好。结构揭示了： ATP 结合模式 金属离子配位环境 潜在的催化机制 该结构为后续的功能研究和药物设计提供了重要基础。"}];export{t as default};
